SELECT INTERFACE_SCHEDULE_ID, SCHEDULE_CODE, COMPANY_CODE, SCHEDULE_NAME, SCHEDULE_DESC, EXECUTION_PROGRAM, APPLY_FROM_DATE, APPLY_TO_DATE, MONTH, WEEK, DAY, HOUR, MINUTES, STATUS, SYSTEM_BATCH_YN, LAST_EXECUTION_DATE, EXTCUTION_MESSAGE, BATCH_YYYYMM, BATCH_YYYYMM_YN, EXEC_TYPE, EXEC_DAILY_PERIOD, EXEC_MONTHLY_PERIOD, EXEC_MANUAL_START_YYYYMM, EXEC_MANUAL_END_YYYYMM, TO_CHAR(CREATE_DATE, 'RRRR-MM-DD') AS CREATE_DATE, CREATE_BY, TO_CHAR(UPDATE_DATE, 'RRRR-MM-DD') AS UPDATE_DATE, UPDATE_BY FROM INTERFACE_SCHEDULE WHERE COMPANY_CODE = #{COMPANY_CODE}
AND INTERFACE_SCHEDULE_ID = #{INTERFACE_SCHEDULE_ID}
AND SYSTEM_BATCH_YN = #{SEARCH_SYSTEM_BATCH_YN}
AND SCHEDULE_CODE = #{SEARCH_KEY_WORD}
AND SCHEDULE_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND SCHEDULE_CODE LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
AND SCHEDULE_NAME = #{SEARCH_KEY_WORD}
AND SCHEDULE_NAME LIKE #{SEARCH_KEY_WORD}|| '%'
AND SCHEDULE_NAME LIKE '%'||#{SEARCH_KEY_WORD}|| '%'

SELECT IF_CODE ,COMPANY_CODE ,IF_NAME ,SOURCE_TABLE ,TARGET_TABLE ,HISTORY_TABLE ,VRIFY_PROGRAM_NAME ,SOURCE_PROGRAM_NAME ,INTERFACE_TYPE ,RETURN_COLUMN_NAME ,RETURN_COLUMN_VALUE ,RETURN_MSG_COLUMN_NAME ,REMARK ,USING_YN ,ATTRIBUTE01 ,ATTRIBUTE02 ,ATTRIBUTE03 ,ATTRIBUTE04 ,ATTRIBUTE05 ,TO_CHAR(CREATE_DATE, 'RRRR-MM-DD') AS CREATE_DATE ,CREATE_BY ,TO_CHAR(UPDATE_DATE, 'RRRR-MM-DD') AS UPDATE_DATE ,UPDATE_BY ,TRANS_PROGRAM_NAME ,TRANS_COMPANY_CODE_YN ,TRANS_DIVISION_CODE_YN ,EXCEL_UPLOAD_YN ,ITEM_TYPE FROM INTERFACE_ITEM_MST A WHERE A.COMPANY_CODE = #{COMPANY_CODE}
AND USING_YN = #{SEARCH_USING_YN}
AND IF_CODE = #{SEARCH_KEY_WORD}
AND IF_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND IF_CODE LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
AND IF_NAME = #{SEARCH_KEY_WORD}
AND IF_NAME LIKE #{SEARCH_KEY_WORD}|| '%'
AND IF_NAME LIKE '%'||#{SEARCH_KEY_WORD}|| '%'

SELECT A.INTG_INTERFACE_TRANS_ID ,A.IF_CODE ,A.COMPANY_CODE ,A.DIVISION_CODE ,A.TOTAL_ROWS ,TO_CHAR(A.TRANS_DATE, 'RRRR-MM-DD') AS TRANS_DATE ,A.TRANS_STATUS ,A.ERROR_MESSAGE ,TO_CHAR(A.CREATE_DATE, 'RRRR-MM-DD') AS CREATE_DATE ,A.CREATE_BY ,TO_CHAR(A.UPDATE_DATE, 'RRRR-MM-DD') AS UPDATE_DATE ,A.UPDATE_BY ,A.SCHEDULE_CODE ,A.IF_PARAM ,A.STATUS ,A.BATCH_STATUS ,A.ERROR_YN ,A.GROUP_ID ,A.ORG_ID ,A.START_TIME ,A.INTERFACE_ID ,A.INTERFACE_TYPE ,A.FROM_DATE ,A.TO_DATE FROM INTG_INTERFACE_TRANS A INNER JOIN INTERFACE_ITEM_MST B ON A.COMPANY_CODE = B.COMPANY_CODE AND A.IF_CODE = B.IF_CODE WHERE A.COMPANY_CODE = #{COMPANY_CODE} AND A.SCHEDULE_CODE = #{SEARCH_SCHEDULE_CODE}
AND A.IF_CODE = #{SEARCH_KEY_WORD}
AND A.IF_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND A.IF_CODE LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
AND B.IF_NAME = #{SEARCH_KEY_WORD}
AND B.IF_NAME LIKE #{SEARCH_KEY_WORD}|| '%'
AND B.IF_NAME LIKE '%'||#{SEARCH_KEY_WORD}|| '%'

SELECT IIT.INTG_INTERFACE_TRANS_ID ,IIT.IF_CODE ,IIM.IF_NAME ,IIT.COMPANY_CODE ,IIT.DIVISION_CODE ,IIT.TOTAL_ROWS ,TO_CHAR(IIT.TRANS_DATE, 'RRRR-MM-DD HH24:MI:SS') AS TRANS_DATE ,IIT.TRANS_STATUS ,IIT.ERROR_MESSAGE ,TO_CHAR(IIT.CREATE_DATE, 'RRRR-MM-DD HH24:MI:SS') AS CREATE_DATE ,IIT.CREATE_BY ,TO_CHAR(IIT.UPDATE_DATE, 'RRRR-MM-DD HH24:MI:SS') AS UPDATE_DATE ,IIT.UPDATE_BY ,IIT.SCHEDULE_CODE ,IIT.IF_PARAM ,IIT.STATUS ,IIT.BATCH_STATUS ,DECODE(IIT.TRANS_STATUS, '1', 'SUCCEED', '2', 'ERROR', 0, 'WORKING', '') TRANS_STATUS_NAME ,IIT.ERROR_YN ,IIT.GROUP_ID ,IIT.ORG_ID ,TO_CHAR(IIT.START_TIME, 'RRRR-MM-DD HH24:MI:SS') AS START_TIME ,IIT.INTERFACE_ID ,IIT.INTERFACE_TYPE ,IIT.FROM_DATE ,IIT.TO_DATE FROM INTRFC_RECORD_MST IIT INNER JOIN INTRFC_MST IIM ON IIT.IF_CODE = IIM.IF_CODE AND IIT.COMPANY_CODE = IIM.COMPANY_CODE WHERE IIT.COMPANY_CODE = #{COMPANY_CODE}
AND IIT.SCHEDULE_CODE = #{SCHEDULE_CODE}
AND IIT.TRANS_STATUS = #{TRANS_STATUS}
AND IIT.IF_CODE = #{SEARCH_IF_CODE}
AND IIT.TRANS_DATE BETWEEN TO_DATE(REPLACE(#{CAL_FROM_DATE},'-',''), 'RRRRMMDD') AND TO_DATE(REPLACE(#{CAL_TO_DATE},'-',''), 'RRRRMMDD')
ORDER BY INTG_INTERFACE_TRANS_ID DESC

SELECT COUNT(*) AS CNT
  FROM COM_AUTHOR_GROUP
 WHERE COMPANY_CODE = #{COMPANY_CODE}
   AND AUTHOR_GROUP_CODE = #{AUTHOR_GROUP_CODE}

