SELECT COUNT(*) AS CNT
  FROM COM_MENU M
 WHERE M.MENU_ID = #{MENU_ID}

SELECT A.IMPDEC_NO ,A.LNE_NO ,A.POUCH_NO ,A.ITEM_CODE ,A.USGQTY --사용형태(01:환급신청서, 02 기납증, 03 분증) ,CASE WHEN USE_TYPE = '01' THEN '환급신청서' WHEN USE_TYPE = '02' THEN '기납증' WHEN USE_TYPE = '03' THEN '분증' END AS USE_TYPE_NAME ,USE_PRESENTN_NO ,USE_THNG_SEQ ,USE_RAWMTRL_SEQ ,TO_CHAR(A.CREATE_DATE, 'RRRR-MM-DD HH24:mi:SS') AS CREATE_DATE FROM INCME_LOCAL_BNT_HSTRY A WHERE A.COMPANY_CODE = #{COMPANY_CODE} AND A.CREATE_DATE BETWEEN TO_DATE(REPLACE(#{CAL_SEARCH_FROM_DATE}, '-',''), 'RRRRMMDD') AND TO_DATE(REPLACE(#{CAL_SEARCH_TO_DATE}, '-',''), 'RRRRMMDD')
AND A.USE_TYPE = #{USE_TYPE}
AND A.IMPDEC_NO = #{SEARCH_KEY_WORD}
AND A.IMPDEC_NO LIKE #{SEARCH_KEY_WORD}|| '%'
AND A.IMPDEC_NO LIKE '%'|| #{SEARCH_KEY_WORD}|| '%'
AND A.USE_PRESENTN_NO = #{SEARCH_KEY_WORD}
AND A.USE_PRESENTN_NO LIKE #{SEARCH_KEY_WORD}|| '%'
AND A.USE_PRESENTN_NO LIKE '%'|| #{SEARCH_KEY_WORD}|| '%'
AND A.ITEM_CODE = #{SEARCH_KEY_WORD}
AND A.ITEM_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND A.ITEM_CODE LIKE '%'|| #{SEARCH_KEY_WORD}|| '%'

