UPDATE INTERFACE_MASTER
   SET STATUS = 'N',
       UPDATE_DATE = SYSDATE,
       UPDATE_BY = #{UPDATE_BY}
 WHERE COMPANY_CODE = #{COMPANY_CODE}
   AND IF_CODE = #{IF_CODE}

