SELECT COUNT(1) AS IF_COUNT
  FROM ${TARGET_TABLE_NAME} A
 WHERE A.${TARGET_COL} BETWEEN #{FROM_DATE} AND #{TO_DATE}
   AND A.COMPANY_CODE = #{COMPANY_CODE}

