UPDATE INTERFACE_MASTER A
   SET A.STATUS = #{STATUS_FLAG},
       UPDATE_DATE = SYSDATE,
       UPDATE_BY = #{UPDATE_BY}
 WHERE A.COMPANY_CODE = #{COMPANY_CODE}
   AND A.IF_CODE = #{IF_CODE}

